// Run the conformance kit on Flowable (C22, C23): every scenario of spec/conformance/kit.yaml,
// with BPMN generated by the studio, on an embedded Flowable engine.
//   npx tsx engines/flowable/run-kit.ts [CK-ID ...] [--verbose]
import * as fs from 'node:fs';
import * as path from 'node:path';
import { loadKit, runScenario, type KitResult } from '../../src/conformance/kit.js';
import { openReadEnv } from '../../src/env.js';
import { FLOWABLE_DIR, buildHarness, flowableAdapter } from './adapter.js';

const args = process.argv.slice(2);
const verbose = args.includes('--verbose');
const only = args.filter((a) => !a.startsWith('--'));
// The content: the connected branch, or an in-memory fake seeded from content-configurations/ (R-11-21).
const { env } = await openReadEnv();
const kit = loadKit(env);
buildHarness();
const adapter = flowableAdapter(env);
const byId = new Map<string, any>(kit.manifest.scenarios.map((s: any) => [s.id, s]));
const results: KitResult[] = [];
for (const m of kit.manifest.scenarios) {
  if (only.length && !only.includes(m.id)) continue;
  const sc = kit.scenarios.scenarios.find((s: any) => s.id === m.id);
  const t0 = Date.now();
  const r: KitResult = sc
    ? await runScenario(env, kit, sc, byId.get(m.id), adapter)
    : { id: m.id, construct: m.construct, title: m.title, passed: false, expected: m.expect, actual: [], checks: [], error: 'No scenario content' };
  results.push(r);
  const failed = r.checks.filter((c) => !c.passed).map((c) => `${c.what}: expected ${JSON.stringify(c.expected)}, got ${JSON.stringify(c.actual)}`);
  const obsFile = path.join(FLOWABLE_DIR, 'out', m.id, 'observation.json');
  const engineNotes = fs.existsSync(obsFile) ? (JSON.parse(fs.readFileSync(obsFile, 'utf8')).notes ?? []) : [];
  console.log(`${r.passed ? 'PASS' : 'FAIL'}  ${r.id.padEnd(14)} ${((Date.now() - t0) / 1000).toFixed(1).padStart(5)}s  ${r.passed ? '' : [...failed, r.error ? `error: ${r.error}` : ''].filter(Boolean).join('; ')}`);
  if (verbose || !r.passed) {
    console.log(`      trace: ${r.actual.join(' | ')}`);
    for (const n of [...(r.notes ?? []), ...engineNotes]) console.log(`      note: ${n}`);
  }
}
const pass = results.filter((r) => r.passed).length;
fs.writeFileSync(path.join(FLOWABLE_DIR, 'out', 'results.json'), JSON.stringify(results, null, 2));
console.log(`${pass} of ${results.length} conformance scenarios pass on Flowable`);
process.exitCode = pass === results.length ? 0 : 1;
